package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen0Test {

    private static final double DELTA = 1e-15;



    @Test
    public void testPow_NaNAndInfinity() {
        // x is NaN
        assertTrue(Double.isNaN(FastMath.pow(Double.NaN, 2.0)));

        // x is Positive Infinity
        assertTrue(Double.isInfinite(FastMath.pow(Double.POSITIVE_INFINITY, 2.0)));
        assertEquals(0.0, FastMath.pow(Double.POSITIVE_INFINITY, -2.0), DELTA);
        assertTrue(Double.isNaN(FastMath.pow(Double.POSITIVE_INFINITY, Double.NaN)));

        // x is Negative Infinity
        assertEquals(0.0, FastMath.pow(Double.NEGATIVE_INFINITY, -2.0), DELTA); // y < 0, y is even integer (logic check)
        // Note: The code has specific logic for Negative Infinity:
        // if y < 0 and y is odd integer -> -0.0
        assertEquals(-0.0, FastMath.pow(Double.NEGATIVE_INFINITY, -3.0), DELTA);
        // if y > 0 and y is odd integer -> -Infinity
        assertEquals(Double.NEGATIVE_INFINITY, FastMath.pow(Double.NEGATIVE_INFINITY, 3.0), DELTA);
        assertTrue(Double.isNaN(FastMath.pow(Double.NEGATIVE_INFINITY, Double.NaN)));

        // y is Positive Infinity
        assertTrue(Double.isNaN(FastMath.pow(1.0, Double.POSITIVE_INFINITY))); // x*x == 1.0
        assertTrue(Double.isNaN(FastMath.pow(-1.0, Double.POSITIVE_INFINITY))); // x*x == 1.0
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(2.0, Double.POSITIVE_INFINITY), DELTA);
        assertEquals(0.0, FastMath.pow(0.5, Double.POSITIVE_INFINITY), DELTA);

        // y is Negative Infinity
        assertTrue(Double.isNaN(FastMath.pow(1.0, Double.NEGATIVE_INFINITY)));
        assertTrue(Double.isNaN(FastMath.pow(-1.0, Double.NEGATIVE_INFINITY)));
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(0.5, Double.NEGATIVE_INFINITY), DELTA);
        assertEquals(0.0, FastMath.pow(2.0, Double.NEGATIVE_INFINITY), DELTA);
    }








}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen0Test {

    private static final double DELTA = 1e-15;





    @Test
    public void testPow_ZeroBase() {
        assertEquals(0.0, FastMath.pow(0.0, 2.0), DELTA);
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(0.0, -2.0), DELTA);

        // Negative Zero base
        double negZero = -0.0;
        // if y > 0 and y is odd integer -> -0.0
        assertEquals(-0.0, FastMath.pow(negZero, 3.0), DELTA);
        // if y < 0 and y is odd integer -> -Infinity
        assertEquals(Double.NEGATIVE_INFINITY, FastMath.pow(negZero, -3.0), DELTA);
    }






}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen0Test {

    private static final double DELTA = 1e-15;







    @Test
    public void testPow_NegativeBase() {
        // y is not integer
        assertTrue(Double.isNaN(FastMath.pow(-2.0, 0.5)));

        // y is integer
        assertEquals(4.0, FastMath.pow(-2.0, 2.0), DELTA);
        assertEquals(-8.0, FastMath.pow(-2.0, 3.0), DELTA);

        // Large y (beyond TWO_POWER_52)
        double largeY = Math.pow(2, 53); 
        // pow(-x, y) logic
        assertEquals(FastMath.pow(2.0, largeY), FastMath.pow(-2.0, largeY), DELTA);
    }




}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen0Test {

    private static final double DELTA = 1e-15;









    @Test
    public void testPow_LargeY() {
        // Test the branch for y >= 8e298 or y <= -8e298
        double extremeY = 1e300;
        // This will likely result in Infinity or 0 based on x, but triggers the branch
        double res = FastMath.pow(1.1, extremeY);
        assertTrue(Double.isInfinite(res) || res == 0.0);

        double extremeYNeg = -1e300;
        double resNeg = FastMath.pow(1.1, extremeYNeg);
        assertTrue(resNeg == 0.0 || Double.isInfinite(resNeg));
    }


}

